     1→import { useState, useCallback, useEffect } from "react";
     2→import { Settings, PanelLeftClose } from "lucide-react";
     3→import { Button } from "@/components/ui/button";
     4→import { syncChannels } from "@/hooks";
     5→import { useTranslation } from "react-i18next";
     6→import { motion, AnimatePresence, useReducedMotion } from "framer-motion";
     7→import { cn } from "@/lib/utils";
     8→import { useLocation } from "react-router-dom";
     9→import {
    10→  Tooltip,
    11→  TooltipContent,
    12→  TooltipProvider,
    13→  TooltipTrigger,
    14→} from "@/components/ui/tooltip";
    15→import { useDesktopRouting } from "@/hooks/use-desktop-routing";
    16→import type { SettingsSection } from "./types";
    17→import {
    18→  DEFAULT_SETTINGS_SECTION,
    19→  SECTIONS,
    20→  VALID_SECTIONS,
    21→  easeOutExpo,
    22→  SETTINGS_SIDEBAR_COLLAPSED_KEY,
    23→} from "./constants";
    24→import { GeneralSection } from "./general-section";
    25→import { AccountSection } from "./account-section";
    26→import { ShortcutsSection } from "./shortcuts-section";
    27→import { NotificationsSection } from "./notifications-section";
    28→import { SettingsGatewayPage } from "./settings-gateway";
    29→import { SettingsChannelsPage } from "./settings-channels";
    30→import { SettingsExecutorsPage } from "./settings-executors";
    31→import { SettingsModelPage } from "./settings-model";
    32→import { SettingsAgentsPage } from "./settings-agents";
    33→import { SettingsMcpPage } from "./settings-mcp";
    34→import { SettingsSkillsPage } from "./settings-skills";
    35→import { SettingsSandboxPage } from "./settings-sandbox";
    36→import { EnvironmentSection } from "./environment-section";
    37→import { TerminalFontsSection } from "./terminal-fonts-section";
    38→import { SettingsOverlay } from "./settings-overlay";
    39→import { SettingsVoice } from "./settings-voice";
    40→import { StorageSection } from "./storage-section";
    41→import { DeveloperSection } from "./developer-section";
    42→import { AboutSection } from "./about-section";
    43→
    44→export function SettingsPage() {
    45→  const { t } = useTranslation();
    46→  const prefersReducedMotion = useReducedMotion();
    47→  const location = useLocation();
    48→  const { openSettings } = useDesktopRouting();
    49→
    50→  // Get section from URL path (e.g., /settings/agents -> "agents")
    51→  const getSectionFromPath = (): SettingsSection => {
    52→    const pathSection = location.pathname.split("/settings/")[1];
    53→    if (pathSection && VALID_SECTIONS.includes(pathSection as SettingsSection)) {
    54→      return pathSection as SettingsSection;
    55→    }
    56→    return DEFAULT_SETTINGS_SECTION;
    57→  };
    58→
    59→  const [activeSection, setActiveSection] = useState<SettingsSection>(
    60→    getSectionFromPath
    61→  );
    62→
    63→  // Collapsed state for settings sidebar
    64→  const [collapsed, setCollapsed] = useState(() => {
    65→    const saved = localStorage.getItem(SETTINGS_SIDEBAR_COLLAPSED_KEY);
    66→    return saved === "true";
    67→  });
    68→
    69→  // Persist collapsed state to localStorage
    70→  useEffect(() => {
    71→    localStorage.setItem(SETTINGS_SIDEBAR_COLLAPSED_KEY, String(collapsed));
    72→  }, [collapsed]);
    73→
    74→  const toggleCollapsed = () => setCollapsed((prev) => !prev);
    75→
    76→  // Sync URL with active section (used in sidebar navigation)
    77→  // Pre-load data when navigating to certain sections
    78→  const handleSectionChange = useCallback((section: SettingsSection) => {
    79→    setActiveSection(section);
    80→    openSettings(section);
    81→
    82→    // Pre-sync channel data when navigating to channels section
    83→    if (section === "channels") {
    84→      syncChannels();
    85→    }
    86→  }, [openSettings]);
    87→
    88→  // Update active section when URL changes
    89→  useEffect(() => {
    90→    const sectionFromPath = getSectionFromPath();
    91→    if (sectionFromPath !== activeSection) {
    92→      setActiveSection(sectionFromPath);
    93→    }
    94→    // Pre-sync data for specific sections on URL change (deep link support)
    95→    if (sectionFromPath === "channels") {
    96→      syncChannels();
    97→    }
    98→  }, [location.pathname]);
    99→
   100→  // Animation variants for content transitions
   101→  const tabContentVariants = {
   102→    initial: {
   103→      opacity: 0,
   104→      x: prefersReducedMotion ? 0 : 20,
   105→    },
   106→    animate: {
   107→      opacity: 1,
   108→      x: 0,
   109→      transition: {
   110→        duration: prefersReducedMotion ? 0 : 0.3,
   111→        ease: easeOutExpo,
   112→      },
   113→    },
   114→    exit: {
   115→      opacity: 0,
   116→      x: prefersReducedMotion ? 0 : -20,
   117→      transition: {
   118→        duration: prefersReducedMotion ? 0 : 0.2,
   119→      },
   120→    },
   121→  };
   122→
   123→  // Container animation variants
   124→  const containerVariants = {
   125→    hidden: { opacity: 0 },
   126→    visible: {
   127→      opacity: 1,
   128→      transition: {
   129→        staggerChildren: prefersReducedMotion ? 0 : 0.05,
   130→        delayChildren: prefersReducedMotion ? 0 : 0.05,
   131→      },
   132→    },
   133→  };
   134→
   135→  const itemVariants = {
   136→    hidden: { opacity: 0, y: prefersReducedMotion ? 0 : 12 },
   137→    visible: {
   138→      opacity: 1,
   139→      y: 0,
   140→      transition: {
   141→        duration: prefersReducedMotion ? 0 : 0.3,
   142→        ease: easeOutExpo,
   143→      },
   144→    },
   145→  };
   146→
   147→  // Render section content
   148→  const renderSectionContent = () => {
   149→    switch (activeSection) {
   150→      case "general":
   151→        return <GeneralSection key="general" />;
   152→      case "account":
   153→        return <AccountSection key="account" />;
   154→      case "shortcuts":
   155→        return <ShortcutsSection key="shortcuts" />;
   156→      case "notifications":
   157→        return <NotificationsSection key="notifications" />;
   158→      case "gateway":
   159→        return <SettingsGatewayPage key="gateway" />;
   160→      case "channels":
   161→        return <SettingsChannelsPage key="channels" />;
   162→      case "executors":
   163→        return <SettingsExecutorsPage key="executors" />;
   164→      case "model":
   165→        return <SettingsModelPage key="model" />;
   166→      case "agents":
   167→        return <SettingsAgentsPage key="agents" />;
   168→      case "mcp":
   169→        return <SettingsMcpPage key="mcp" />;
   170→      case "skills":
   171→        return <SettingsSkillsPage key="skills" />;
   172→      case "sandbox":
   173→        return <SettingsSandboxPage key="sandbox" />;
   174→      case "environment":
   175→        return <EnvironmentSection key="environment" />;
   176→      case "terminalFonts":
   177→        return <TerminalFontsSection key="terminalFonts" />;
   178→      case "overlay":
   179→        return <SettingsOverlay key="overlay" />;
   180→      case "voice":
   181→        return <SettingsVoice key="voice" />;
   182→      case "storage":
   183→        return <StorageSection key="storage" />;
   184→      case "developer":
   185→        return <DeveloperSection key="developer" />;
   186→      case "about":
   187→        return <AboutSection key="about" />;
   188→      default:
   189→        return null;
   190→    }
   191→  };
   192→
   193→  return (
   194→    <TooltipProvider delayDuration={0}>
   195→      <motion.div
   196→        className="h-full flex flex-col md:flex-row"
   197→        variants={containerVariants}
   198→        initial="hidden"
   199→        animate="visible"
   200→      >
   201→        {/* Left Navigation Sidebar */}
   202→        <motion.nav
   203→          className={cn(
   204→            "shrink-0 border-b md:border-b-0 md:border-r bg-muted/30 transition-all duration-300 overflow-hidden whitespace-nowrap flex flex-col",
   205→            collapsed ? "w-16" : "w-56"
   206→          )}
   207→          variants={itemVariants}
   208→          initial="visible"
   209→        >
   210→          {/* Header with collapse toggle - matches main sidebar h-14 */}
   211→          <div className={cn(
   212→            "flex h-14 items-center border-b border-border",
   213→            collapsed ? "justify-center px-2" : "justify-between px-3"
   214→          )}>
   215→            {collapsed ? (
   216→              // Collapsed: clickable settings icon to expand
   217→              <Tooltip>
   218→                <TooltipTrigger asChild>
   219→                  <button
   220→                    type="button"
   221→                    onClick={toggleCollapsed}
   222→                    className="transition-transform duration-200 hover:scale-105 p-2"
   223→                  >
   224→                    <Settings className="h-5 w-5 text-primary" />
   225→                  </button>
   226→                </TooltipTrigger>
   227→                <TooltipContent side="right">
   228→                  {t("settings.title")}
   229→                </TooltipContent>
   230→              </Tooltip>
   231→            ) : (
   232→              // Expanded: show title and collapse button
   233→              <>
   234→                <h1 className="text-lg font-semibold font-serif">
   235→                  {t("settings.title")}
   236→                </h1>
   237→                <Tooltip>
   238→                  <TooltipTrigger asChild>
   239→                    <Button
   240→                      variant="ghost"
   241→                      size="icon"
   242→                      className="h-8 w-8 shrink-0 text-muted-foreground hover:text-foreground"
   243→                      onClick={toggleCollapsed}
   244→                    >
   245→                      <PanelLeftClose className="h-4 w-4" />
   246→                    </Button>
   247→                  </TooltipTrigger>
   248→                  <TooltipContent side="right">
   249→                    {t("sidebar.collapse")}
   250→                  </TooltipContent>
   251→                </Tooltip>
   252→              </>
   253→            )}
   254→          </div>
   255→
   256→          {/* Navigation items */}
   257→          {collapsed ? (
   258→            // Collapsed view - icons only with tooltips
   259→            <div className="flex flex-col gap-1 py-4 overflow-y-auto flex-1 min-h-0">
   260→              {SECTIONS.map((section) => {
   261→                const Icon = section.icon;
   262→                const isActive = activeSection === section.id;
   263→
   264→                return (
   265→                  <div key={section.id} className="grid place-items-center w-full">
   266→                    <Tooltip>
   267→                      <TooltipTrigger asChild>
   268→                        <button
   269→                          onClick={() => handleSectionChange(section.id)}
   270→                          className={cn(
   271→                            "flex items-center justify-center h-10 w-10 rounded-lg",
   272→                            "transition-all duration-200",
   273→                            "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
   274→                            isActive
   275→                              ? "bg-primary text-primary-foreground shadow-sm"
   276→                              : "text-muted-foreground hover:bg-muted hover:text-foreground"
   277→                          )}
   278→                        >
   279→                          <Icon className={cn("h-4 w-4", isActive && "scale-110")} />
   280→                        </button>
   281→                      </TooltipTrigger>
   282→                      <TooltipContent side="right">
   283→                        {t(section.labelKey)}
   284→                      </TooltipContent>
   285→                    </Tooltip>
   286→                  </div>
   287→                );
   288→              })}
   289→            </div>
   290→          ) : (
   291→            // Expanded view - full items
   292→            <ul className="space-y-1 py-4 px-2 overflow-y-auto flex-1 min-h-0">
   293→              {SECTIONS.map((section) => {
   294→                const Icon = section.icon;
   295→                const isActive = activeSection === section.id;
   296→
   297→                return (
   298→                  <li key={section.id}>
   299→                    <button
   300→                      onClick={() => handleSectionChange(section.id)}
   301→                      className={cn(
   302→                        "w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm",
   303→                        "transition-all duration-200",
   304→                        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
   305→                        isActive
   306→                          ? [
   307→                              "bg-primary text-primary-foreground font-medium",
   308→                              "shadow-sm",
   309→                            ]
   310→                          : [
   311→                              "text-muted-foreground",
   312→                              "hover:bg-muted hover:text-foreground",
   313→                            ]
   314→                      )}
   315→                    >
   316→                      <Icon
   317→                        className={cn(
   318→                          "h-4 w-4 shrink-0",
   319→                          "transition-transform duration-200",
   320→                          isActive && "scale-110"
   321→                        )}
   322→                      />
   323→                      <span>{t(section.labelKey)}</span>
   324→                    </button>
   325→                  </li>
   326→                );
   327→              })}
   328→            </ul>
   329→          )}
   330→        </motion.nav>
   331→
   332→      {/* Right Content Area */}
   333→      <div className={cn(
   334→        "flex-1 overflow-auto",
   335→        // Full-width pages need no padding
   336→        ["agents", "mcp", "skills"].includes(activeSection) ? "" : "p-6"
   337→      )}>
   338→        <AnimatePresence mode="wait">
   339→          <motion.div
   340→            key={activeSection}
   341→            variants={tabContentVariants}
   342→            initial="initial"
   343→            animate="animate"
   344→            exit="exit"
   345→            className={cn(
   346→              // Full-width pages need full height
   347→              ["agents", "mcp", "skills"].includes(activeSection) ? "h-full" : "max-w-2xl"
   348→            )}
   349→          >
   350→            {renderSectionContent()}
   351→          </motion.div>
   352→        </AnimatePresence>
   353→      </div>
   354→      </motion.div>
   355→    </TooltipProvider>
   356→  );
   357→}
   358→

