     1→import { Sparkles } from "lucide-react";
     2→import { Button } from "@/components/ui/button";
     3→import { Switch } from "@/components/ui/switch";
     4→import {
     5→  Select,
     6→  SelectContent,
     7→  SelectItem,
     8→  SelectTrigger,
     9→  SelectValue,
    10→} from "@/components/ui/select";
    11→import { ThemeSwitcher } from "./theme-switcher";
    12→import { useAppStore } from "@/stores";
    13→import { useTranslation } from "react-i18next";
    14→import { LANGUAGES } from "@/i18n/languages";
    15→import { changeLanguage } from "@/i18n";
    16→import { useNavigate } from "react-router-dom";
    17→import { SettingsItem, SectionHeader } from "./components";
    18→import { TIMEZONES } from "./constants";
    19→
    20→export function GeneralSection() {
    21→  const { t, i18n } = useTranslation();
    22→  const navigate = useNavigate();
    23→  const {
    24→    language,
    25→    setLanguage,
    26→    alwaysShowTextDirection,
    27→    setAlwaysShowTextDirection,
    28→    weekStartsOnMonday,
    29→    setWeekStartsOnMonday,
    30→    dateFormat,
    31→    setDateFormat,
    32→    autoSetTimezone,
    33→    setAutoSetTimezone,
    34→    timezone,
    35→    setTimezone,
    36→    setOnboardingCompleted,
    37→  } = useAppStore();
    38→
    39→  // Handle language change
    40→  const handleLanguageChange = async (langCode: string) => {
    41→    await changeLanguage(langCode);
    42→    setLanguage(langCode);
    43→  };
    44→
    45→  // Current language for reactivity (fallback to store value)
    46→  const currentLanguage = i18n.language || language || "en";
    47→
    48→  // Get timezone label using i18n
    49→  const getTimezoneLabel = (tz: typeof TIMEZONES[number] | string) => {
    50→    if (typeof tz === "string") {
    51→      const found = TIMEZONES.find((item) => item.value === tz);
    52→      if (found) {
    53→        return t(found.labelKey);
    54→      }
    55→      return tz;
    56→    }
    57→    return t(tz.labelKey);
    58→  };
    59→
    60→  return (
    61→    <div className="space-y-6">
    62→      <div>
    63→        <h2 className="text-xl font-semibold font-serif mb-1">
    64→          {t("settings.sections.general")}
    65→        </h2>
    66→        <p className="text-sm text-muted-foreground">
    67→          {t("settings.generalDescription", { defaultValue: "General application settings" })}
    68→        </p>
    69→      </div>
    70→
    71→      {/* Preferences Section */}
    72→      <div className="rounded-xl border bg-card p-4">
    73→        <SectionHeader title={t("settings.sections.preferences")} />
    74→
    75→        <div className="py-4 border-b border-border">
    76→          <div className="mb-3">
    77→            <h3 className="text-sm font-medium text-foreground">{t("settings.appearance")}</h3>
    78→            <p className="text-sm text-muted-foreground mt-0.5">{t("settings.appearanceDescription")}</p>
    79→          </div>
    80→          <ThemeSwitcher />
    81→        </div>
    82→      </div>
    83→
    84→      {/* Language & Time Section */}
    85→      <div className="rounded-xl border bg-card p-4">
    86→        <SectionHeader title={t("settings.sections.languageAndTime")} />
    87→
    88→        <SettingsItem
    89→          title={t("settings.language")}
    90→          description={t("settings.languageDescription")}
    91→        >
    92→          <Select value={currentLanguage} onValueChange={handleLanguageChange}>
    93→            <SelectTrigger className="w-[180px]">
    94→              <SelectValue>
    95→                {LANGUAGES.find((l) => l.code === currentLanguage)?.nativeName || currentLanguage}
    96→              </SelectValue>
    97→            </SelectTrigger>
    98→            <SelectContent>
    99→              {LANGUAGES.map((lang) => (
   100→                <SelectItem key={lang.code} value={lang.code}>
   101→                  {lang.nativeName}
   102→                </SelectItem>
   103→              ))}
   104→            </SelectContent>
   105→          </Select>
   106→        </SettingsItem>
   107→
   108→        <SettingsItem
   109→          title={t("settings.alwaysShowTextDirection")}
   110→          description={t("settings.alwaysShowTextDirectionDescription")}
   111→        >
   112→          <Switch
   113→            checked={alwaysShowTextDirection}
   114→            onCheckedChange={setAlwaysShowTextDirection}
   115→          />
   116→        </SettingsItem>
   117→
   118→        <SettingsItem
   119→          title={t("settings.weekStartsOnMonday")}
   120→          description={t("settings.weekStartsOnMondayDescription")}
   121→        >
   122→          <Switch
   123→            checked={weekStartsOnMonday}
   124→            onCheckedChange={setWeekStartsOnMonday}
   125→          />
   126→        </SettingsItem>
   127→
   128→        <SettingsItem
   129→          title={t("settings.dateFormat")}
   130→          description={t("settings.dateFormatDescription")}
   131→        >
   132→          <Select value={dateFormat} onValueChange={(value) => setDateFormat(value as "relative" | "absolute")}>
   133→            <SelectTrigger className="w-[180px]">
   134→              <SelectValue>
   135→                {dateFormat === "relative" ? t("settings.relativeDate") : t("settings.absoluteDate")}
   136→              </SelectValue>
   137→            </SelectTrigger>
   138→            <SelectContent>
   139→              <SelectItem value="relative">{t("settings.relativeDate")}</SelectItem>
   140→              <SelectItem value="absolute">{t("settings.absoluteDate")}</SelectItem>
   141→            </SelectContent>
   142→          </Select>
   143→        </SettingsItem>
   144→
   145→        <SettingsItem
   146→          title={t("settings.autoSetTimezone")}
   147→          description={t("settings.autoSetTimezoneDescription")}
   148→        >
   149→          <Switch
   150→            checked={autoSetTimezone}
   151→            onCheckedChange={setAutoSetTimezone}
   152→          />
   153→        </SettingsItem>
   154→
   155→        <SettingsItem
   156→          title={t("settings.timezone")}
   157→          description={t("settings.timezoneDescription")}
   158→        >
   159→          <Select value={timezone} onValueChange={setTimezone}>
   160→            <SelectTrigger className="w-[180px]">
   161→              <SelectValue>{getTimezoneLabel(timezone)}</SelectValue>
   162→            </SelectTrigger>
   163→            <SelectContent>
   164→              {TIMEZONES.map((tz) => (
   165→                <SelectItem key={tz.value} value={tz.value}>
   166→                  {t(tz.labelKey)}
   167→                </SelectItem>
   168→              ))}
   169→            </SelectContent>
   170→          </Select>
   171→        </SettingsItem>
   172→      </div>
   173→
   174→      {/* Onboarding Section */}
   175→      <div className="rounded-xl border bg-card p-4">
   176→        <SectionHeader title={t("settings.sections.setup")} />
   177→        <div className="flex items-center justify-between py-4">
   178→          <div className="flex items-center gap-3">
   179→            <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-primary/10">
