   482→/** @deprecated Use registry.match() instead — kept only for legacy compatibility */
   483→export function urlToLocation(url: string): DesktopLocation | null {
   484→  const parsed = new URL(url, "http://desktop.local");
   485→  const pathname = parsed.pathname;
   486→  const segments = pathname.split("/").filter(Boolean);
   487→  const suffix = { search: parsed.search || undefined, hash: parsed.hash || undefined };
   488→
   489→  if (pathname === "/documents") return { kind: "documents", ...suffix };
   490→  if (pathname === "/devices/pair") return { kind: "device-pair", ...suffix };
   491→  if (pathname === "/publish" || pathname === "/my-packages" || pathname === "/analytics") {
   492→    return { kind: "global-route", path: `${pathname}${parsed.search}${parsed.hash}` };
   493→  }
   494→
   495→  if (segments[0] === "settings") {
   496→    const section = normalizeSettingsSection(segments[1] ? decodePathPart(segments[1]) : "general");
   497→    return { kind: "settings", section, ...suffix };
   498→  }
   499→
   500→  if (segments[0] === "agent" && segments[1]) {
   501→    return { kind: "agent-detail", agentId: decodePathPart(segments[1]), workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   502→  }
   503→  if (segments[0] === "executor" && segments[1]) {
   504→    return { kind: "executor-detail", executorType: decodePathPart(segments[1]), workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   505→  }
   506→  if (segments[0] === "skill" && segments[1]) {
   507→    return { kind: "skill-detail", skillId: decodePathPart(segments[1]), agentId: parsed.searchParams.get("agent_id") ?? "", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   508→  }
   509→  if (segments[0] === "mcp-server" && segments[1]) {
   510→    return { kind: "mcp-server-detail", serverName: decodePathPart(segments[1]), executorType: parsed.searchParams.get("executor_type") ?? "CLAUDE_CODE", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   511→  }
   512→  if (segments[0] === "subagent" && segments[1]) {
   513→    return { kind: "subagent-detail", configId: decodePathPart(segments[1]), executorType: parsed.searchParams.get("executor_type") ?? "CLAUDE_CODE", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   514→  }
   515→  if (segments[0] === "prompt" && segments[1]) {
   516→    return { kind: "prompt-detail", promptId: decodePathPart(segments[1]), executorType: parsed.searchParams.get("executor_type") ?? "CLAUDE_CODE", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   517→  }
   518→  if (segments[0] === "command" && segments[1]) {
   519→    return { kind: "command-detail", commandId: decodePathPart(segments[1]), executorType: parsed.searchParams.get("executor_type") ?? "CLAUDE_CODE", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   520→  }
   521→
   522→  if (segments[0] === "workspace" && segments[1] === "page") {
   523→    const workspaceId = parsed.searchParams.get("workspace_id");
   524→    const pageSlug = extractLegacyPageSlug(parsed.searchParams.get("page_path"));
   525→    if (workspaceId && pageSlug) {
   526→      return { kind: "workspace-page", workspaceId, pageSlug, hash: parsed.hash || undefined };
   527→    }
   528→  }
   529→
   530→  if (segments[0] === "workspace" && segments[1]) {
   531→    const workspaceId = decodePathPart(segments[1]);
   532→    if (segments.length === 2) return { kind: "workspace-home", workspaceId, ...suffix };
   533→    if ((segments[2] === "pages" || segments[2] === "apps") && !segments[3]) return { kind: "workspace-section", workspaceId, section: "pages", ...suffix };
   534→    if (segments[2] === "agents" && !segments[3]) return { kind: "workspace-section", workspaceId, section: "agent", ...suffix };
   535→    if (segments[2] === "agent" && segments[3]) return { kind: "workspace-agent-detail", workspaceId, agentId: decodePathPart(segments[3]), ...suffix };
   536→    if (segments[2] === "executor" && segments[3]) return { kind: "workspace-executor-detail", workspaceId, executorType: decodePathPart(segments[3]), ...suffix };
   537→    if (segments[2] === "web") {
   538→      const targetUrl = parsed.searchParams.get("url");
   539→      const title = parsed.searchParams.get("title");
   540→      if (targetUrl && title) {
   541→        return { kind: "workspace-web", workspaceId, url: targetUrl, title, sourcePageSlug: parsed.searchParams.get("source_page") ?? undefined, webId: parsed.searchParams.get("web_id") ?? undefined, hash: parsed.hash || undefined };
   542→      }
   543→    }
   544→    if (segments[2] === "page") {
   545→      const pageSlug = extractWorkspacePageSlug(pathname);
   546→      if (pageSlug) return { kind: "workspace-page", workspaceId, pageSlug, hash: parsed.hash || undefined };
   547→    }
   548→    const section = decodePathPart(segments[2]);
   549→    if (isWorkspaceSection(section)) return { kind: "workspace-section", workspaceId, section, ...suffix };
   550→  }
   551→
   552→  if (pathname === "/") return null;
   553→  return { kind: "global-route", path: `${pathname}${parsed.search}${parsed.hash}` };
   554→}
